    60|export function resolveGithubRepoIdentity(): GithubRepoIdentity {
    61|  const fromUrl = readEnv('GITHUB_REPO_URL');
    62|  if (fromUrl) {
    63|    const parsed = parseGithubRepoUrl(fromUrl);
    64|    if (parsed) return parsed;
