    66|  const owner = readEnv('GITHUB_OWNER');
    67|  const repo = readEnv('GITHUB_REPO') || readEnv('GITHUB_REPOSITORY');
    68|  if (owner && repo) return { owner, repo };
    69|  const repository = readEnv('GITHUB_REPOSITORY');
    70|  if (repository && repository.includes('/')) {
    71|    const parsed = parseGithubRepoUrl(repository);
    72|    if (parsed) return parsed;
