   165|export async function githubCommitFile(input: {
   166|  path: string;
   167|  content: string;
   168|  message?: string;
   169|  branch?: string;
   170|}): Promise<GithubCommitResult> {
   171|  const repo = resolveGithubRepoIdentity();
   172|  const branch = (input.branch || readEnv('GITHUB_DEFAULT_BRANCH') || 'main').trim();
   173|  const repoPath = sanitizeRepoPath(input.path);
   174|  const content = input.content;
   175|  if (!content) {
   176|    return { ok: false, commitSha: null, commitUrl: null, fileUrl: null, mode: 'update_existing_file', error: 'File content is required.' };
   177|  }
   178|  if (content.length > MAX_CONTENT_LENGTH) {
   179|    return { ok: false, commitSha: null, commitUrl: null, fileUrl: null, mode: 'update_existing_file', error: `File content too large (max ${MAX_CONTENT_LENGTH} chars).` };
   180|  }
   181|  const message = (input.message || `IVX Senior Dev Worker update ${repoPath}`).trim();
   182|  const encoded = encodeRepoPath(repoPath);
   183|
   184|  // Fetch existing file to get its SHA (required for updates).
   185|  const contentUrl = `${GITHUB_API}/repos/${repo.owner}/${repo.repo}/contents/${encoded}?ref=${encodeURIComponent(branch)}`;
   186|  let existingSha = '';
   187|  try {
   188|    const existingRes = await fetch(contentUrl, { method: 'GET', headers: githubHeaders() });
   189|    if (existingRes.ok) {
   190|      const existingData = readRecord(await parseJsonResponse(existingRes));
   191|      existingSha = typeof existingData.sha === 'string' ? existingData.sha : '';
   192|    }
   193|  } catch {
   194|    // File may not exist yet — proceed without SHA (create new file).
   195|  }
   196|
   197|  const mode: GithubCommitResult['mode'] = existingSha ? 'update_existing_file' : 'create_new_file';
   198|
   199|  try {
   200|    const res = await fetch(`${GITHUB_API}/repos/${repo.owner}/${repo.repo}/contents/${encoded}`, {
   201|      method: 'PUT',
   202|      headers: githubHeaders(),
   203|      body: JSON.stringify({
   204|        message,
   205|        content: Buffer.from(content, 'utf8').toString('base64'),
   206|        branch,
   207|        ...(existingSha ? { sha: existingSha } : {}),
   208|      }),
   209|    });
