   211|      const errBody = await parseJsonResponse(res);
   212|      const errMsg = readRecord(errBody).message || `GitHub commit failed with HTTP ${res.status}`;
   213|      return { ok: false, commitSha: null, commitUrl: null, fileUrl: null, mode, error: String(errMsg) };
   214|    }
   215|    const data = readRecord(await parseJsonResponse(res));
   216|    const commit = readRecord(data.commit);
   217|    const file = readRecord(data.content);
   218|    return {
   219|      ok: true,
   220|      commitSha: typeof commit.sha === 'string' ? commit.sha : null,
   221|      commitUrl: typeof commit.html_url === 'string' ? commit.html_url : (typeof commit.url === 'string' ? commit.url : null),
   222|      fileUrl: typeof file.html_url === 'string' ? file.html_url : null,
   223|      mode,
   224|      error: null,
   225|    };
   226|  } catch (err) {
   227|    return { ok: false, commitSha: null, commitUrl: null, fileUrl: null, mode, error: err instanceof Error ? err.message : String(err) };
